CREATE TABLE IF NOT EXISTS `1780942049_wp5c_wc_admin_notes` ( `note_id` bigint unsigned NOT NULL AUTO_INCREMENT, `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL, `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL, `locale` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL, `title` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL, `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL, `content_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci, `status` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL, `source` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL, `date_created` datetime NOT NULL DEFAULT '0000-00-00 00:00:00', `date_reminder` datetime DEFAULT NULL, `is_snoozable` tinyint(1) NOT NULL DEFAULT '0', `layout` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '', `image` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL, `is_deleted` tinyint(1) NOT NULL DEFAULT '0', `is_read` tinyint(1) NOT NULL DEFAULT '0', `icon` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'info', PRIMARY KEY (`note_id`)) ENGINE=InnoDB AUTO_INCREMENT=174 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
INSERT INTO `1780942049_wp5c_wc_admin_notes` (`note_id`, `name`, `type`, `locale`, `title`, `content`, `content_data`, `status`, `source`, `date_created`, `date_reminder`, `is_snoozable`, `layout`, `image`, `is_deleted`, `is_read`, `icon`) VALUES (1,'wayflyer_bnpl_q4_2021','marketing','en_US','Grow your business with funding through Wayflyer','Fast, flexible financing to boost cash flow and help your business grow – one fee, no interest rates, penalties, equity, or personal guarantees. Based on your store’s performance, Wayflyer provides funding and analytical insights to invest in your business.','{}','pending','woocommerce.com','2023-10-03 00:17:00',NULL,0,'plain','',0,0,'info'),(2,'wc_shipping_mobile_app_usps_q4_2021','marketing','en_US','Print and manage your shipping labels with WooCommerce Shipping and the WooCommerce Mobile App','Save time by printing, purchasing, refunding, and tracking shipping labels generated by <a href=\"https://woocommerce.com/woocommerce-shipping/\">WooCommerce Shipping</a> – all directly from your mobile device!','{}','pending','woocommerce.com','2023-10-03 00:17:00',NULL,0,'plain','',0,0,'info'),(3,'woocommerce-services','info','en_US','WooCommerce Shipping & Tax','WooCommerce Shipping &amp; Tax helps get your store \"ready to sell\" as quickly as possible. You create your products. We take care of tax calculation, payment processing, and shipping label printing! Learn more about the extension that you just installed.','{}','pending','woocommerce.com','2023-10-03 00:17:00',NULL,0,'plain','',0,0,'info'),(4,'your-first-product','info','en_US','Your first product','That’s huge! You’re well on your way to building a successful online store — now it’s time to think about how you’ll fulfill your orders.<br /><br />Read our shipping guide to learn best practices and options for putting together your shipping strategy. And for WooCommerce stores in the United States, you can print discounted shipping labels via USPS with <a href=\"https://href.li/?https://woocommerce.com/shipping\" target=\"_blank\">WooCommerce Shipping</a>.','{}','pending','woocommerce.com','2023-10-03 00:17:00',NULL,0,'plain','',0,0,'info'),(5,'wc-admin-optimizing-the-checkout-flow','info','en_US','Optimizing the checkout flow','It’s crucial to get your store’s checkout as smooth as possible to avoid losing sales. Let’s take a look at how you can optimize the checkout experience for your shoppers.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(6,'wc-payments-qualitative-feedback','info','en_US','WooPayments setup - let us know what you think','Congrats on enabling WooPayments for your store. Please share your feedback in this 2 minute survey to help us improve the setup process.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(7,'share-your-feedback-on-paypal','info','en_US','Share your feedback on PayPal','Share your feedback in this 2 minute survey about how we can make the process of accepting payments more useful for your store.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(8,'google_listings_and_ads_install','marketing','en_US','Drive traffic and sales with Google','Reach online shoppers to drive traffic and sales for your store by showcasing products across Google, for free or with ads.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(9,'wc-subscriptions-security-update-3-0-15','info','en_US','WooCommerce Subscriptions security update!','We recently released an important security update to WooCommerce Subscriptions. To ensure your site’s data is protected, please upgrade <strong>WooCommerce Subscriptions to version 3.0.15</strong> or later.<br /><br />Click the button below to view and update to the latest Subscriptions version, or log in to <a href=\"https://woocommerce.com/my-dashboard\">WooCommerce.com Dashboard</a> and navigate to your <strong>Downloads</strong> page.<br /><br />We recommend always using the latest version of WooCommerce Subscriptions, and other software running on your site, to ensure maximum security.<br /><br />If you have any questions we are here to help — just <a href=\"https://woocommerce.com/my-account/create-a-ticket/\">open a ticket</a>.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(10,'woocommerce-core-update-5-4-0','info','en_US','Update to WooCommerce 5.4.1 now','WooCommerce 5.4.1 addresses a checkout issue discovered in WooCommerce 5.4. We recommend upgrading to WooCommerce 5.4.1 as soon as possible.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(11,'wcpay-promo-2020-11','marketing','en_US','wcpay-promo-2020-11','wcpay-promo-2020-11','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(12,'wcpay-promo-2020-12','marketing','en_US','wcpay-promo-2020-12','wcpay-promo-2020-12','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(13,'ppxo-pps-upgrade-paypal-payments-1','info','en_US','Get the latest PayPal extension for WooCommerce','Heads up! There’s a new PayPal on the block!<br /><br />Now is a great time to upgrade to our latest <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">PayPal extension</a> to continue to receive support and updates with PayPal.<br /><br />Get access to a full suite of PayPal payment methods, extensive currency and country coverage, and pay later options with the all-new PayPal extension for WooCommerce.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(14,'ppxo-pps-upgrade-paypal-payments-2','info','en_US','Upgrade your PayPal experience!','Get access to a full suite of PayPal payment methods, extensive currency and country coverage, offer subscription and recurring payments, and the new PayPal pay later options.<br /><br />Start using our <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">latest PayPal today</a> to continue to receive support and updates.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(15,'woocommerce-core-sqli-july-2021-need-to-update','update','en_US','Action required: Critical vulnerabilities in WooCommerce','In response to a critical vulnerability identified on July 13, 2021, we are working with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br />Our investigation into this vulnerability is ongoing, but <strong>we wanted to let you know now about the importance of updating immediately</strong>.<br /><br />For more information on which actions you should take, as well as answers to FAQs, please urgently review our blog post detailing this issue.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(16,'woocommerce-blocks-sqli-july-2021-need-to-update','update','en_US','Action required: Critical vulnerabilities in WooCommerce Blocks','In response to a critical vulnerability identified on July 13, 2021, we are working with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br />Our investigation into this vulnerability is ongoing, but <strong>we wanted to let you know now about the importance of updating immediately</strong>.<br /><br />For more information on which actions you should take, as well as answers to FAQs, please urgently review our blog post detailing this issue.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(17,'woocommerce-core-sqli-july-2021-store-patched','update','en_US','Solved: Critical vulnerabilities patched in WooCommerce','In response to a critical vulnerability identified on July 13, 2021, we worked with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br /><strong>Your store has been updated to the latest secure version(s)</strong>. For more information and answers to FAQs, please review our blog post detailing this issue.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(18,'woocommerce-blocks-sqli-july-2021-store-patched','update','en_US','Solved: Critical vulnerabilities patched in WooCommerce Blocks','In response to a critical vulnerability identified on July 13, 2021, we worked with the WordPress Plugins Team to deploy software updates to stores running WooCommerce (versions 3.3 to 5.5) and the WooCommerce Blocks feature plugin (versions 2.5 to 5.5).<br /><br /><strong>Your store has been updated to the latest secure version(s)</strong>. For more information and answers to FAQs, please review our blog post detailing this issue.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(19,'habit-moment-survey','marketing','en_US','We’re all ears! Share your experience so far with WooCommerce','We’d love your input to shape the future of WooCommerce together. Feel free to share any feedback, ideas or suggestions that you have.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(20,'woocommerce-core-paypal-march-2022-updated','update','en_US','Security auto-update of WooCommerce','<strong>Your store has been updated to the latest secure version of WooCommerce</strong>. We worked with WordPress to deploy PayPal Standard security updates for stores running WooCommerce (version 3.5 to 6.3). It’s recommended to disable PayPal Standard, and use <a href=\"https://woocommerce.com/products/woocommerce-paypal-payments/\" target=\"_blank\">PayPal Payments</a> to accept PayPal.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(21,'woocommerce-core-paypal-march-2022-updated-nopp','update','en_US','Security auto-update of WooCommerce','<strong>Your store has been updated to the latest secure version of WooCommerce</strong>. We worked with WordPress to deploy security updates related to PayPal Standard payment gateway for stores running WooCommerce (version 3.5 to 6.3).','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(22,'pinterest_03_2022_update','marketing','en_US','Your Pinterest for WooCommerce plugin is out of date!','Update to the latest version of Pinterest for WooCommerce to continue using this plugin and keep your store connected with Pinterest. To update, visit <strong>Plugins &gt; Installed Plugins</strong>, and click on “update now” under Pinterest for WooCommerce.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(23,'store_setup_survey_survey_q2_2022','survey','en_US','Como está indo a configuração da sua loja?','Nosso objetivo é garantir que você tenha todas as ferramentas certas para começar a configurar sua loja da maneira mais tranquila possível.\r\nAdoraríamos saber se atingimos nosso objetivo e como podemos melhorar. Para saber sua opinião, criamos uma pesquisa de 2 minutos.','{}','unactioned','woocommerce.com','2023-10-10 01:32:33',NULL,0,'plain','',0,0,'info'),(24,'woocommerce-payments-august-2022-need-to-update','update','en_US','Action required: Please update WooCommerce Payments','An updated secure version of WooCommerce Payments is available – please ensure that you’re using the latest patch version. For more information on what action you need to take, please review the article below.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(25,'woocommerce-payments-august-2022-store-patched','update','en_US','WooCommerce Payments has been automatically updated','You’re now running the latest secure version of WooCommerce Payments. We’ve worked with the WordPress Plugins team to deploy a security update to stores running WooCommerce Payments (version 3.9 to 4.5). For further information, please review the article below.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(26,'needs-update-eway-payment-gateway-rin-2022-12-20','update','en_US','Security vulnerability patched in WooCommerce Eway Gateway','In response to a potential vulnerability identified in WooCommerce Eway Gateway versions 3.1.0 to 3.5.0, we’ve worked to deploy security fixes and have released an updated version.\r\nNo external exploits have been detected, but we recommend you update to your latest supported version 3.1.26, 3.2.3, 3.3.1, 3.4.6, or 3.5.1','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(27,'updated-eway-payment-gateway-rin-2022-12-20','update','en_US','WooCommerce Eway Gateway has been automatically updated','Your store is now running the latest secure version of WooCommerce Eway Gateway. We worked with the WordPress Plugins team to deploy a software update to stores running WooCommerce Eway Gateway (versions 3.1.0 to 3.5.0) in response to a security vulnerability that was discovered.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(28,'ecomm-wc-navigation-survey-2023','info','en_US','Navigating WooCommerce on WordPress.com','We are improving the WooCommerce navigation on WordPress.com and would love your help to make it better! Please share your experience with us in this 2-minute survey.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(29,'woopay-beta-merchantrecruitment-04MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','WooPay, a new express checkout feature built into WooCommerce Payments, is now available —and we’re inviting you to be one of the first to try it. \r\n<br><br>\r\nBoost conversions by offering your customers a simple, secure way to pay with a single click.\r\n<br><br>\r\nGet started in seconds.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(30,'woocommerce-wcpay-march-2023-update-needed','update','en_US','Action required: Security update for WooCommerce Payments','<strong>Your store requires a security update for WooCommerce Payments</strong>. Please update to the latest version of WooCommerce Payments immediately to address a potential vulnerability discovered on March 22. For more information on how to update, visit this WooCommerce Developer Blog Post.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(31,'tap_to_pay_iphone_q2_2023_no_wcpay','marketing','en_US','Accept in-person contactless payments on your iPhone','Tap to Pay on iPhone and WooCommerce Payments is quick, secure, and simple to set up — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(32,'woocommerce-WCPreOrders-april-2023-update-needed','update','en_US','Action required: Security update of WooCommerce Pre-Orders extension','<strong>Your store requires a security update for the WooCommerce Pre-Orders extension</strong>. Please update the WooCommerce Pre-Orders extension immediately to address a potential vulnerability discovered on April 11.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(33,'woopay-beta-merchantrecruitment-update-04MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','WooPay, a new express checkout feature built into WooCommerce Payments, is now available — and you’re invited to try it. \r\n<br /><br />\r\nBoost conversions by offering your customers a simple, secure way to pay with a single click.\r\n<br /><br />\r\nUpdate WooCommerce Payments to get started.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(34,'woopay-beta-existingmerchants-noaction-27APR23','info','en_US','WooPay is back!','Thanks for previously trying WooPay, the express checkout feature built into WooCommerce Payments. We’re excited to announce that WooPay availability has resumed. No action is required on your part.\r\n<br /><br />\r\nYou can now continue boosting conversions by offering your customers a simple, secure way to pay with a single click.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(35,'woopay-beta-existingmerchants-update-27APR23','info','en_US','WooPay is back!','Thanks for previously trying WooPay, the express checkout feature built into WooCommerce Payments. We’re excited to announce that WooPay availability has resumed.\r\n<br /><br />\r\n\r\nUpdate to the latest WooCommerce Payments version to continue boosting conversions by offering your customers a simple, secure way to pay with a single click.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(36,'woopay-beta-merchantrecruitment-short-04MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(37,'woopay-beta-merchantrecruitment-short-update-04MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, our new express checkout feature. <br>Boost conversions by letting customers pay with a single click. <br><br>Update to the latest version of WooCommerce Payments to get started.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(38,'woopay-beta-merchantrecruitment-short-06MAY23-TESTA','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(39,'woopay-beta-merchantrecruitment-short-06MAY23-TESTB','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(40,'woopay-beta-merchantrecruitment-short-06MAY23-TESTC','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(41,'woopay-beta-merchantrecruitment-short-06MAY23-TESTD','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(42,'woopay-beta-merchantrecruitment-short-09MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, a new express checkout feature for WooCommerce Payments. \r\n<br><br>\r\nBoost conversions by letting customers pay with a single click.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(43,'woopay-beta-merchantrecruitment-short-update-09MAY23','info','en_US','Increase conversions with WooPay — our fastest checkout yet','Be one of the first to try WooPay, our new express checkout feature. <br>Boost conversions by letting customers pay with a single click. <br><br>Update to the latest version of WooCommerce Payments to get started.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(44,'woocommerce-WCstripe-May-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce Stripe plugin','<strong>Your store requires a security update for the WooCommerce Stripe plugin</strong>. Please update the WooCommerce Stripe plugin immediately to address a potential vulnerability.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(45,'woocommerce-WCPayments-June-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce Payments','<strong>Your store requires a security update for the WooCommerce Payments plugin</strong>. Please update the WooCommerce Payments plugin immediately to address a potential vulnerability.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(46,'woocommerce-WCSubscriptions-June-2023-updated-needed','marketing','en_US','Action required: Security update of WooCommerce Subscriptions','<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(47,'woocommerce-WCReturnsWarranty-June-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce Returns and Warranty Requests extension','<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(48,'woocommerce-WCOPC-June-2023-updated-needed','update','en_US','Action required: Security update of WooCommerce One Page Checkout','<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(49,'woocommerce-WCGC-July-2023-update-needed','update','en_US','Action required: Security update of WooCommerce GoCardless Extension','<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(50,'woocommerce-shipping-fedex-api-outage-2023-07-16','warning','en_US','Scheduled FedEx API outage — July 2023','On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(51,'wcship-2023-07-hazmat-update-needed','update','en_US','Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension','<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(52,'woocommerce-WCStripe-Aug-2023-update-needed','update','en_US','Action required: Security update for WooCommerce Stripe plugin','<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(53,'woocommerce-WCStripe-Aug-2023-security-updated','update','en_US','Security update of WooCommerce Stripe plugin','<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(54,'woocommerce-WooPayments-Aug-2023-update-needed','update','en_US','Action required: Security update for WooPayments (WooCommerce Payments) plugin','<strong>Your shop requires an important security update for the WooPayments (WooCommerce Payments) extension</strong>. The fix for this vulnerability was released on July 31. Please update immediately.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(55,'woocommerce-WooPayments-Aug-2023-security-updated','update','en_US','Security update of WooPayments (WooCommerce Payments) plugin','<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(56,'avalara_q3-2023_noAvaTax','marketing','en_US','Automatically calculate VAT in real time','Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(57,'woo-activation-survey-blockers-22AUG23','info','en_US','How can we help you get that first sale?','Your feedback is vital. Please take a minute to share your experience of setting up your new store and whether anything is preventing you from making those first few sales. Together, we can make Woo even better!','{}','unactioned','woocommerce.com','2023-10-03 00:31:21',NULL,0,'plain','',1,1,'info'),(58,'woocommerce-usermeta-Sept2023-productvendors','update','en_US','Your store requires a security update','<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.','{}','pending','woocommerce.com','2023-10-03 00:17:01',NULL,0,'plain','',0,0,'info'),(59,'wc-admin-wc-helper-connection','info','en_US','Conectar ao WooCommerce.com','Conecte-se para receber notificações e atualizações importantes do produto.','{}','unactioned','woocommerce-admin','2023-10-03 00:26:27',NULL,0,'plain','',1,1,'info'),(60,'wc-admin-customizing-product-catalog','info','en_US','Como personalizar seu catálogo do produtos','Você deseja que seu catálogo de produtos e imagens tenham uma ótima aparência e se alinhem à sua marca. Este guia fornecerá todas as dicas necessárias para que seus produtos fiquem ótimos em sua loja.','{}','unactioned','woocommerce-admin','2023-10-03 00:54:28',NULL,0,'plain','',1,1,'info'),(62,'wc-admin-mobile-app','info','en_US','Instale o aplicativo Woo','Instale o aplicativo do WooCommerce para gerenciar pedidos, receber notificações de vendas e visualizar as principais métricas, onde quer que você esteja.','{}','unactioned','woocommerce-admin','2023-10-05 02:51:27',NULL,0,'plain','',1,1,'info'),(63,'wc-admin-onboarding-payments-reminder','info','en_US','Comece a aceitar pagamentos em sua loja!','Faça pagamentos com o provedor certo para você, escolha entre mais de 100 sistemas de pagamento para o WooCommerce.','{}','unactioned','woocommerce-admin','2023-10-08 02:34:32',NULL,0,'plain','',0,0,'info'),(64,'wc-admin-usage-tracking-opt-in','info','en_US','Ajude o WooCommerce a melhorar ativando o rastreamento de uso.','A coleta de dados de uso nos permite melhorar o WooCommerce. Sua loja será considerada à medida que avaliarmos novos recursos, julgarmos a qualidade de uma atualização ou determinarmos se uma melhoria faz sentido. Você sempre pode visitar as <a href=\"https://maquinas.umaprevia.com.br/wp-admin/admin.php?page=wc-settings&#038;tab=advanced&#038;section=woocommerce_com\" target=\"_blank\">Configurações</a> e optar por parar de compartilhar dados. <a href=\"https://woocommerce.com/usage-tracking?utm_medium=product\" target=\"_blank\">Saiba mais</a> sobre quais dados coletamos.','[]','unactioned','woocommerce-admin','2023-10-10 01:32:33',NULL,0,'plain','',0,0,'info'),(65,'Klarna_10OCT23','marketing','en_US','Klarna is now available','This is a test. Klarna is now available.','{}','pending','woocommerce.com','2023-10-12 01:20:38',NULL,0,'plain','',0,0,'info'),(66,'wc_com_in_person_payments_card_sale_US_inbox_note_q4_23','marketing','en_US','Save 35% on a WooPayments card reader','Have you been thinking about selling your products or services in person? Now’s the perfect time to do so, as we’re discounting our M2 card readers by 35%! Securely process payments wherever your business takes you, with full store and inventory sync. Don’t miss out — this offer ends October 29, 2023.','{}','pending','woocommerce.com','2023-10-13 01:41:53',NULL,0,'plain','',0,0,'info'),(67,'wc_com_in_person_payments_card_sale_UK_inbox_note_q4_23','marketing','en_US','Save 35% on a WooPayments card reader','Have you been thinking about selling your products or services in person? Now’s the perfect time to do so, as we’re discounting our WisePad 3 card readers by 35%! Securely process payments wherever your business takes you, with full store and inventory sync. Don’t miss out — this offer ends 29th October 2023.','{}','pending','woocommerce.com','2023-10-13 01:41:53',NULL,0,'plain','',0,0,'info'),(68,'wc_com_in_person_payments_card_sale_CA_inbox_note_q4_23','marketing','en_US','Save 35% on a WooPayments card reader','Have you been thinking about selling your products or services in person? Now’s the perfect time to do so, as we’re discounting our WisePad 3 card readers by 35%! Securely process payments wherever your business takes you, with full store and inventory sync. Don’t miss out — this offer ends October 29, 2023.','{}','pending','woocommerce.com','2023-10-13 01:41:53',NULL,0,'plain','',0,0,'info'),(69,'woocommerce-STRIPE-Oct-2023-update-needed','update','en_US','Action required: Security update for WooCommerce Stripe Gateway','<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.','{}','pending','woocommerce.com','2023-10-18 03:34:32',NULL,0,'plain','',0,0,'info'),(70,'wc_admin_WooPay_Q4_2023','marketing','en_US','Convert more sales with our fastest checkout yet','Enable WooPay and offer the only single-click checkout experience built by Woo, for Woo. Give shoppers the power to pay instantly and securely speed through checkout, even if it\'s their first visit. Add it for free with one tap in your WooPayments dashboard.','{}','pending','woocommerce.com','2023-10-28 02:40:05',NULL,0,'plain','',0,0,'info'),(71,'wc_admin_WooPay_Oct30_2023','marketing','en_US','Convert more sales with our fastest checkout yet','Enable WooPay and offer the only single-click checkout experience built by Woo, for Woo. Give shoppers the power to pay instantly and securely speed through checkout, even if it\'s their first visit. Add it for free with one tap in your WooPayments dashboard.','{}','pending','woocommerce.com','2023-11-03 00:59:51',NULL,0,'plain','',0,0,'info'),(72,'paypal_paylater_q4_23','marketing','en_US','Boost your sales this holiday season with PayPal','Set yourself up for success this holiday season by allowing customers to pay the way they prefer. With the latest version of PayPal Payments, you can accept PayPal, Venmo (US), Pay Later*, credit and debit cards, and popular alternative payment methods in one secure solution.','{}','pending','woocommerce.com','2023-11-07 00:55:51',NULL,0,'plain','',0,0,'info'),(73,'tap_to_pay_iphone_q4_2023_no_woopayments','marketing','en_US','Accept in-person contactless payments on your iPhone','Tap to Pay on iPhone and WooPayments is quick, secure, and simple to set up — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person.','{}','pending','woocommerce.com','2023-12-06 00:58:27',NULL,0,'plain','',0,0,'info'),(74,'tap_to_pay_iphone_q4_2023_with_woopayments','marketing','en_US','Accept in-person contactless payments on your iPhone','Tap to Pay on iPhone is quick, secure, and simple to set up in WooPayments — no extra terminals or card readers are needed. Accept contactless debit and credit cards, Apple Pay, and other NFC digital wallets in person in a few short steps!','{}','pending','woocommerce.com','2023-12-06 00:58:27',NULL,0,'plain','',0,0,'info'),(75,'amazon-mcf-reviews-2023-12-07','marketing','en_US','Enjoying Amazon MCF for WooCommerce?','We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!','{}','pending','woocommerce.com','2023-12-07 01:29:24',NULL,0,'plain','',0,0,'info'),(76,'wc-admin-real-time-order-alerts','info','en_US','Receba alertas de pedidos em tempo real em qualquer lugar','Receba notificações sobre a atividade da loja, incluindo novos pedidos e análises de produtos diretamente em seus dispositivos móveis com o aplicativo Woo.','{}','unactioned','woocommerce-admin','2024-01-01 01:33:48',NULL,0,'plain','',0,0,'info'),(77,'amazon_pay_reactivate_q1-24','marketing','en_US','Special offer: Activate 0% promo rate for Amazon Pay','For a limited time, Woo merchants who register with Amazon Pay can enjoy a promotional rate of 0% on all transaction fees for 30 days. Valid for businesses based in the United Kingdom. Terms and conditions apply.','{}','pending','woocommerce.com','2024-01-10 00:54:42',NULL,0,'plain','',0,0,'info'),(78,'remove_estimated_deposits_2024','marketing','en_US','Estimated deposits are going away','To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.','{}','pending','woocommerce.com','2024-01-20 01:02:47',NULL,0,'plain','',0,0,'info'),(79,'custom_order_attribution_inbox_q1_2024','marketing','en_US','NEW: Custom Order Attribution','Order attribution tracking is now available for all Woo stores! See whether an order came from a search ad, video, or email. Make better marketing decisions and watch your products go from “maybe” to “must-have.”','{}','pending','woocommerce.com','2024-02-06 02:32:05',NULL,0,'plain','',0,0,'info'),(80,'wc_admin_UKpricingchange_WCPay_Q1_2024','marketing','en_US','Fee Changes for WooPayments in the EEA and UK','WooPayments fees for transactions between the EEA and UK will change as of 1st March, 2024. Transactions between the UK and EEA are now deemed by card networks to be cross-border, thus international payment fees will be applicable. This also changes base processing fees.','{}','pending','woocommerce.com','2024-03-01 03:14:50',NULL,0,'plain','',0,0,'info'),(81,'airwallex_q1_2024','marketing','en_US','Save big on foreign exchange (FX) fees','Boost your international sales by offering Apple Pay, Google Pay, and 60+ local payment methods with Airwallex. Save time and money by settling payments directly in USD, EUR, HKD, SGD, AUD, and more — without the extra FX fees. Simple, cost-effective, fast.','{}','pending','woocommerce.com','2024-03-01 03:14:50',NULL,0,'plain','',0,0,'info'),(82,'wc-admin-manage-orders-on-the-go','info','en_US','Gerencie seus pedidos de qualquer lugar','Procure pedidos, informações de clientes e processe reembolsos em um clique com o aplicativo Woo.','{}','unactioned','woocommerce-admin','2024-03-31 00:58:11',NULL,0,'plain','',0,0,'info'),(83,'checkout_survey_new_users','survey','en_US','We\'d like your feedback on WooCommerce checkout','Your feedback is essential for us to improve the WooCommerce checkout and increase your conversion rate, turning more visitors into customers. Answer a few questions to help us understand your experience. It shouldn\'t take more than 5 minutes of your time.','{}','pending','woocommerce.com','2024-04-19 01:22:28',NULL,0,'plain','',0,0,'info'),(84,'affirm_q2_2024','marketing','en_US','Boost sales and increase average order value with Affirm!','Affirm’s flexible payment options empower customers to get exactly what they want, while making budget-friendly payments. Remove the price barrier and make it even easier for your customers to upgrade, bundle, and add on — with no late fees and clear payment plans. \r\n\r\n* Subject to eligibility. Terms apply.','{}','pending','woocommerce.com','2024-04-25 02:17:06',NULL,0,'plain','',0,0,'info'),(85,'wc-update-db-reminder','update','en_US','A atualização da base de dados do WooCommerce é necessária','O WooCommerce foi atualizado! Para manter tudo funcionando sem problemas, atualizamos a base de dados para a última versão. O processo de atualização da base de dados é executado em segundo plano e pode demorar algum tempo, por isso, seja paciente. Usuários avançados podem, alternativamente, atualizar usando o <a href=\"https://github.com/woocommerce/woocommerce/wiki/Upgrading-the-database-using-WP-CLI\">WP CLI</a>.','{}','actioned','woocommerce-core','2024-04-28 23:28:15',NULL,0,'plain','',0,0,'info'),(86,'checkout_survey_new_users_no_orders','survey','en_US','We\'d like your feedback on WooCommerce checkout','Your feedback is essential for us to improve the WooCommerce checkout and increase your conversion rate, turning more visitors into customers. Answer a few questions to help us understand your experience. It shouldn\'t take more than 5 minutes of your time.','{}','pending','woocommerce.com','2024-05-01 01:47:18',NULL,0,'plain','',0,0,'info'),(87,'wc-admin-launch-checklist','info','en_US','Pronto para lançar sua loja?','Para garantir que você nunca fique com aquela sensação de \"o que eu esqueci\", reunimos uma lista com tudo que é essencial para você verificar antes do lançamento.','{}','unactioned','woocommerce-admin','2024-05-05 01:47:34',NULL,0,'plain','',0,0,'info'),(88,'woocommerce-payfast-may-2024-update-needed','update','en_US','An important update is required for the Payfast Payment Gateway','<strong>Please update to the latest version of the Payfast Payment Gateway for WooCommerce immediately to address a security vulnerability</strong>. This update is required to ensure that your transactions continue to process.','{}','pending','woocommerce.com','2024-05-14 01:26:27',NULL,0,'plain','',0,0,'info'),(89,'mailchimp_q2_2024','marketing','en_US','Level up your marketing to boost sales','Looking for a smart way to kickstart your growth? Mailchimp’s best-in-class email marketing empowers you to create and automate precisely targeted SMS and email campaigns and build long-term relationships with your audience. Enhance your customer experience, track sales, and more by connecting your store to Mailchimp.','{}','pending','woocommerce.com','2024-06-04 01:13:23',NULL,0,'plain','',0,0,'info'),(90,'WC-order-attribution-update-June-2024','update','en_US','An important update is required for WooCommerce','<strong>An important security update for WooCommerce has been released</strong>. It is recommended that you update as quickly as possible.','{}','unactioned','woocommerce.com','2024-06-11 01:01:00',NULL,0,'plain','',0,0,'info'),(91,'checkout_block_update_july_2024','marketing','en_US','UPDATE: The checkout block is getting an upgrade!','We’re improving the checkout block in 2024, starting with WooCommerce 9.0, launching on June 18! The latest release includes streamlined order summary with sticky functionality, better address form layout, and other enhancements to boost conversion.','{}','pending','woocommerce.com','2024-06-19 05:52:02',NULL,0,'plain','',0,0,'info'),(92,'wc-admin-performance-on-mobile','info','en_US','Acompanhe o desempenho da sua loja em dispositivos móveis','Monitore suas vendas e produtos com melhor performance com o aplicativo Woo.','{}','unactioned','woocommerce-admin','2024-06-29 02:03:50',NULL,0,'plain','',0,0,'info'),(93,'bfcm-survey-jul2024','marketing','en_US','Complete our holiday survey and get a $30 coupon','We want to understand how you prepare your store for Black Friday/Cyber Monday and the holidays.\r\n\r\nComplete our 10-minute survey and get $30 USD off an extension from our official Marketplace. Hurry, the survey closes July 15.','{}','pending','woocommerce.com','2024-07-04 02:18:05',NULL,0,'plain','',0,0,'info'),(94,'stripe_newcheckout_q3_2024','marketing','en_US','Upgrade your Stripe checkout for even more payment options','Boost sales, increase order value, and reach new customers with the new checkout from Stripe. Support 23 payment methods, including buy now, pay later methods like Klarna, Afterpay, and Affirm; Bancontact in Europe and Alipay in Asia; and Link, an accelerated checkout experience that autofills payment information.','{}','pending','woocommerce.com','2024-07-05 04:48:16',NULL,0,'plain','',0,0,'info'),(95,'klaviyo_q4_2024','marketing','en_US','Need a marketing solution to help you sell more?','Over 13,000 brands use Klaviyo to grow faster. You can drive 46x ROI with their personalized email, SMS, forms, and product reviews. Start for free today.','{}','pending','woocommerce.com','2024-08-01 01:30:31',NULL,0,'plain','',0,0,'info'),(96,'wnww-recap-july','marketing','en_US','Powerful updates and upgrades in WooCommerce','Have you seen all the latest from Woo? Check out our recent roundup for a look at the newest features, extensions, and insights making WooCommerce perform better than ever.','{}','pending','woocommerce.com','2024-08-14 00:57:33',NULL,0,'plain','',0,0,'info'),(97,'bfcm2024-landing-page','marketing','en_US','The best way to prepare for holiday success','The upcoming holiday season is the busiest time of the year for many online stores. We want to help you make the most of it with an early gift: our first-ever Black Friday Cyber Monday Trends Report. It\'s full of stats, trends, and recommendations to knock your holiday socks off!','{}','pending','woocommerce.com','2024-09-05 02:00:16',NULL,0,'plain','',0,0,'info'),(98,'stripe_securityupdate_q3_2024','update','en_US','Security update required for your Stripe extension','To continue securely accepting payments, you must update your Stripe extension to at least version 8.6, re-authenticate, and turn on the new checkout experience. Review the documentation for instructions on how to make the necessary changes from your WooCommerce dashboard.','{}','pending','woocommerce.com','2024-09-19 01:46:48',NULL,0,'plain','',0,0,'info'),(99,'wc-admin-edit-products-on-the-move','info','en_US','Edite produtos de qualquer lugar','Edite e crie novos produtos do seu dispositivo móvel com o aplicativo Woo','{}','unactioned','woocommerce-admin','2024-10-02 01:10:05',NULL,0,'plain','',0,0,'info'),(100,'paypal_migration_Q3_2024','marketing','en_US','You’re using an outdated version of PayPal','Don\'t miss out on potential sales this holiday season — upgrade your store\'s checkout experience by switching to the all-in-one PayPal Payments extension. Enable customers to pay using Venmo and Pay Later (where available), credit and debit cards, Apple Pay, Google Pay, and country-specific options.','{}','pending','woocommerce.com','2024-10-04 01:11:11',NULL,0,'plain','',0,0,'info'),(101,'paypal_migration_Q3_2024_v2','marketing','en_US','You’re using an outdated version of PayPal','Don\'t miss out on potential sales this holiday season — upgrade your store\'s checkout experience by switching to the all-in-one PayPal Payments extension. Enable customers to pay using Venmo and Pay Later (where available), credit and debit cards, Apple Pay, Google Pay, and country-specific options.','{}','pending','woocommerce.com','2024-10-31 01:19:50',NULL,0,'plain','',0,0,'info'),(102,'mollie_q4_2024','marketing','en_US','Special offer: Zero transaction fees for your first month with Mollie','With seamless checkout, flexible financing, and 30+ local and global payment methods, Mollie is the all-in-one payment solution that enhances the customer experience and helps your business grow. Start your account today and enjoy ZERO transaction fees for the first month. Ts&amp;Cs apply.','{}','pending','woocommerce.com','2024-11-01 01:01:36',NULL,0,'plain','',0,0,'info'),(103,'Renewal_notification_emails_Woosubscriptions_Nov2024','marketing','en_US','WooCommerce Subscriptions just got even better','You can now send automatic email reminders to customers before their subscriptions renew or expire. To enable this for your store, update to the latest version of WooCommerce Subscriptions (don\'t forget to make a backup first) and follow the steps linked below.','{}','pending','woocommerce.com','2024-11-19 01:54:44',NULL,0,'plain','',0,0,'info'),(104,'paypal_promo_Q4_2024','marketing','en_US','Add PayPal to your existing checkout this holiday season','Drive conversion and give customers more confidence to buy when you complement your checkout with PayPal, Venmo, Pay Later, and more. Attract new shoppers and give them a streamlined buying experience with Fastlane, PayPal’s fast and simple guest checkout.','{}','pending','woocommerce.com','2024-11-28 01:14:38',NULL,0,'plain','',0,0,'info'),(105,'sirt-woo-2024-11-xss-admin','update','en_US','An important update is required for WooCommerce','This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>','{}','pending','woocommerce.com','2024-12-04 01:16:43',NULL,0,'plain','',0,0,'info'),(106,'usps-mail-service-to-canada-suspended-dec-2024','update','en_US','Please note: USPS Mail Service to Canada Suspended','The United States Postal Service has temporarily suspended mail service to Canada due to the ongoing Canadian postal workers\' strike. USPS is asking users to refrain from mailing items to Canada at this time.','{}','pending','woocommerce.com','2024-12-06 01:38:49',NULL,0,'plain','',0,0,'info'),(107,'Announce-UPS-WCShipping-Dec2024','marketing','en_US','WooCommerce Shipping now supports select UPS services','Give customers the power and reliability of UPS, directly from your dashboard. Access discounted rates, convenient shipping options, and fast, on-time delivery with UPS on WooCommerce Shipping — and stay tuned for UPS® Ground Saver rates coming in 2025.','{}','pending','woocommerce.com','2024-12-13 01:00:17',NULL,0,'plain','',0,0,'info'),(108,'account-creation-after-checkout-dec2024','marketing','en_US','Offer account creation after checkout','Your customers can now create accounts after they check out on block-based themes. Enable the new “After checkout” block in your account settings and enjoy smoother guest checkout, better conversion, and more repeat business.','{}','pending','woocommerce.com','2024-12-19 01:08:24',NULL,0,'plain','',0,0,'info'),(109,'woocommerce-analytics-order-attribution-promotions-december-2024','marketing','en_US','Discover what drives your sales','Use our powerful <strong>Order Attribution</strong> extension to understand what truly drives your revenue. Track your sales journey, identify your most effective marketing channels, and optimize your sales strategy.','{}','pending','woocommerce.com','2024-12-24 00:56:18',NULL,0,'plain','',0,0,'info'),(110,'affirm_promo_Q1_2025','marketing','en_US','Save up to 50% on merchant fees with Affirm','Kickstart the year with buy now, pay later and get merchant rates as low as 2.9% + 30¢ per transaction for 30 days. Download the extension and complete your application from your WooCommerce dashboard by February 19, 2025 to claim the offer. Terms and conditions apply.','{}','pending','woocommerce.com','2025-01-21 01:11:00',NULL,0,'plain','',0,0,'info'),(111,'new-woo-brand-announcement-feb4-2025','marketing','en_US','Meet the new Woo','WooCommerce has a new look, but underneath, we’re still the same customizable, open-source ecommerce platform you know and love. Plus, we’ve got some major improvements to our platform and product on the way.','{}','pending','woocommerce.com','2025-02-05 04:32:34',NULL,0,'plain','',0,0,'info'),(112,'paypal_bnpl_au_promo_Q1_2025','marketing','en_US','Australian shoppers can Pay in 4 with PayPal','Enable Pay in 4 messaging to let Australian customers know that they can pay over time while you get paid up front and in full. Pay in 4 is included in PayPal Payments at no additional cost. Eligible buyers can pay in four interest-free payments for purchases of $30 to $2,000 AUD. Terms apply.','{}','pending','woocommerce.com','2025-02-12 01:46:41',NULL,0,'plain','',0,0,'info'),(113,'stripe_stripetax_q1_2025','marketing','en_US','Say goodbye to your tax woes','Stripe Tax automatically applies the correct sales tax, VAT, or GST, saving time while keeping you compliant. And with simple automatic filing, you can stop stressing at tax time and focus on growing instead.','{}','pending','woocommerce.com','2025-02-20 02:25:40',NULL,0,'plain','',0,0,'info'),(114,'printful_promo_q1_2025','marketing','en_US','New: sell print-on-demand products, risk-free','Expand your product line with Printful, now available in the WooCommerce Marketplace. Sell custom products with no upfront costs or inventory. This trusted supplier prints, packages, and ships for you, so you can focus on growing your store — and your next big idea.','{}','pending','woocommerce.com','2025-02-26 01:13:34',NULL,0,'plain','',0,0,'info'),(115,'paypal-braintree-sdk-depreciation-2025-02-20','update','en_US','Update required for your PayPal Braintree extension','To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.','{}','pending','woocommerce.com','2025-03-04 01:17:31',NULL,0,'plain','',0,0,'info'),(116,'woo-marketplace-two-year-subscriptions-rin-2025-03-17','marketing','en_US','Save 20% on new two-year subscriptions','We’ve introduced 20% off two-year subscriptions for all products* in the WooCommerce Marketplace. Lock in long-term savings and make sure your store never misses a beat. \r\n\r\n*Some exclusions apply. New purchases only.','{}','pending','woocommerce.com','2025-03-17 01:41:13',NULL,0,'plain','',0,0,'info'),(117,'viva_wallet_migration_q1_2025','update','en_US','Switch to the new Viva.com Smart Checkout','The Viva Wallet extension is no longer being updated and improved. To get the best Viva.com experience, move to the new Smart Checkout. It’s fast, secure, and fully compatible with the latest WooCommerce features.','{}','pending','woocommerce.com','2025-04-04 01:18:44',NULL,0,'plain','',0,0,'info'),(118,'stripe_orderstatus_bug_q2_2025','update','en_US','Action Required: Update Order Status Manager','Update to the latest Order Status Manager (v1.15.5+) to ensure payments are captured. Your version of WooCommerce Order Status Manager can interfere with order processing for payment gateways (including WooCommerce Stripe Gateway v9.2.0+), which may cause orders to process without capturing payment.','{}','pending','woocommerce.com','2025-04-04 01:18:44',NULL,0,'plain','',0,0,'info'),(119,'WooCommerce-Stripe-Gateway-Update-April-2025','update','en_US','Action required: Update WooCommerce Stripe Gateway to v9.4.1','<strong>An important update for WooCommerce Stripe Payment Gateway has been released</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. Please update as soon as possible for optimal store performance. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory</a> for more information.','{}','pending','woocommerce.com','2025-04-19 01:00:02',NULL,0,'plain','',0,0,'info'),(120,'WooCommerce-Stripe-Gateway-Update-Info-April-2025','update','en_US','WooCommerce Stripe Gateway has been updated to v9.4.1','<strong>WooCommerce Stripe Payment Gateway was recently updated</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. No further action is required. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory post </a>for more information.','{}','pending','woocommerce.com','2025-04-19 01:00:02',NULL,0,'plain','',0,0,'info'),(121,'klaviyo_q2_2025','marketing','en_US','Tailor your marketing with data-driven automation','Deliver personalized experiences at scale, simplify your stack, and make your data work for you using Klaviyo’s best-in-class marketing extension for Woo. With advanced segmentation based on actual customer behavior, you can send email and SMS messages that drive revenue and increase loyalty — without adding complexity','{}','pending','woocommerce.com','2025-04-30 02:25:37',NULL,0,'plain','',0,0,'info'),(122,'uk-vat-notice-2025-04-30','warning','en_US','UK VAT numbers are no longer supported','Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement','{}','pending','woocommerce.com','2025-05-06 01:07:17',NULL,0,'plain','',0,0,'info'),(123,'payson-retirement-2025','update','en_US','Payson Form Retirement','Svea Bank is discontinuing the Payson service; the last date for transactions is August 31, 2025. As a result, the Payson Form extension has been removed from WooCommerce.com. Documentation remains available.','{}','pending','woocommerce.com','2025-05-13 01:12:15',NULL,0,'plain','',0,0,'info'),(124,'paypal_q2_2025','marketing','en_US','Power up sales with Pay Later messaging','Help increase your sales and grow cart sizes by letting customers know they have flexible payment options. Merchants see up to an 11% sales lift when they add Pay Later messaging — plus, it integrates seamlessly with your PayPal checkout.','{}','pending','woocommerce.com','2025-05-22 01:01:54',NULL,0,'plain','',0,0,'info'),(125,'paypal-braintree-sdk-depreciation-2025-05-30','update','en_US','Action required: Update the PayPal Braintree extension','Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.','{}','pending','woocommerce.com','2025-05-30 01:10:01',NULL,0,'plain','',0,0,'info'),(126,'tento_q2_2025','marketing','en_US','Get your free business credit score','Strong business credit is the key to better deals, stronger partnerships, and sustainable growth. Tento Business Credit Monitoring helps you catch risks early, secure better financing, and fuel smarter growth — with no impact to your credit.','{}','pending','woocommerce.com','2025-06-05 01:06:17',NULL,0,'plain','',0,0,'info'),(127,'wc-admin-email-improvements','info','en_US','Os e-mails da loja tiveram um upgrade!','Fizemos algumas melhorias interessantes em nossos modelos de e-mail, incluindo designs modernos e fáceis de usar e novas opções de personalização. E se estiver usando um tema de bloco, você pode sincronizar automaticamente seus estilos de tema! Acesse suas configurações de e-mail para explorar os novos recursos.','{}','unactioned','woocommerce-admin','2025-06-20 01:07:40',NULL,0,'plain','',0,0,'info'),(128,'woopayments-multibanco-alipay-wechat-launch-2025-06-23','marketing','en_US','Multibanco, AliPay and WeChat now available in WooPayments','Multibanco, AliPay, and WeChat Pay are now available in WooPayments! Offer trusted local payment methods to customers in key global markets and boost international sales. Geo restrictions apply.','{}','pending','woocommerce.com','2025-06-24 01:27:16',NULL,0,'plain','',0,0,'info'),(129,'woopayments-new-lpms-2025-06-30','marketing','en_US','Get the POS built specifically for Woo stores','Introducing WooCommerce POS, our new point-of-sale solution built to get you up and running quickly with in-person sales. Search products, scan barcodes, apply coupons, and send email receipts — right in the WooCommerce mobile app, with all of your online and physical sales synced in real time — no extra setup required','{}','pending','woocommerce.com','2025-07-01 01:01:53',NULL,0,'plain','',0,0,'info'),(130,'tiktok-webinar-promo-july2025','marketing','en_US','You\'re Invited: TikTok for WooCommerce Webinar','Join us for a free webinar with our friends at TikTok on Tuesday, July 8, at 4 pm UTC. We\'ll cover creative tips and best practices for making content that turns views into sales.','{}','pending','woocommerce.com','2025-07-01 01:01:53',NULL,0,'plain','',0,0,'info'),(131,'woopayments-grabpay-launch-2025-07-07','marketing','en_US','GrabPay now available in WooPayments','Offer GrabPay through WooPayments and make checkout easier for customers across Southeast Asia. Enable it today and expand your reach with a payment method they know and trust.','{}','pending','woocommerce.com','2025-07-08 01:07:32',NULL,0,'plain','',0,0,'info'),(132,'BFCM-25-Survey','marketing','en_US','You’re invited: Take our quick BFCM survey and get 25% off','We’re gathering insights on how businesses prepare for peak sales moments like Black Friday and Cyber Monday — so we can better support you. Take our quick 8-minute survey to share your thoughts and get 25% off your next WooCommerce extension as a thank you.','{}','pending','woocommerce.com','2025-07-15 01:26:14',NULL,0,'plain','',0,0,'info'),(133,'woohoo10-coupon','marketing','en_US','Celebrate and save with WooCommerce 10.0','To mark this milestone release, get 10% off extensions and themes in the official Woo Marketplace. Use code WOOHOO10 at checkout to save on essential tools that help grow your business. Offer ends August 15, 2025. Terms and conditions apply.','{}','unactioned','woocommerce.com','2025-07-22 00:57:43',NULL,0,'plain','',0,0,'info'),(134,'paypaladvantage_q3_2025','marketing','en_US','Add PayPal Checkout and earn up to $1,000*','PayPal Checkout can boost conversion by up to 46% and average order value by up to 62% with no disruption to your checkout. New US merchants who activate by August 31 save 25% on transaction fees for 6 months. Excludes Venmo. Terms apply.*','{}','pending','woocommerce.com','2025-07-23 01:30:20',NULL,0,'plain','',0,0,'info'),(135,'stripe_optimizedcheckout_upgrade_q3_2025','marketing','en_US','Upgrade for a faster, more flexible Stripe checkout','You\'re not on the latest WooCommerce Stripe Payment Gateway version. Upgrade to version 9.8 to access Stripe\'s Optimized Checkout Suite and leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.','{}','pending','woocommerce.com','2025-08-14 01:50:08',NULL,0,'plain','',0,0,'info'),(136,'stripe_optimizedcheckout_enable_q3_2025','marketing','en_US','Unlock dynamic payments and sell more','You’re on the latest WooCommerce Stripe Payment Gateway — now unlock its full potential by enabling the Optimized Checkout Suite. It uses AI models to dynamically surface the most relevant payment methods for each customer, helping you boost conversions.','{}','pending','woocommerce.com','2025-08-14 01:50:08',NULL,0,'plain','',0,0,'info'),(137,'stripe_optimizedcheckout_promotion_q3_2025','marketing','en_US','Upgrade to Stripe for a faster, more flexible checkout','Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.','{}','pending','woocommerce.com','2025-08-16 01:06:55',NULL,0,'plain','',0,0,'info'),(138,'woo-subscription-gifting-bundling-2025-08-18','marketing','en_US','Grow recurring revenue with gifting','WooCommerce Subscriptions now includes gifting. Customers can buy subscriptions for others, helping you reach new shoppers and grow recurring revenue with less effort. Update to the latest version of Subscriptions (7.8.0) to start offering gifting.','{}','pending','woocommerce.com','2025-08-20 01:00:10',NULL,0,'plain','',0,0,'info'),(139,'stripe_optimizedcheckout_competitors_q3_2025','marketing','en_US','Upgrade to the official WooCommerce Stripe Payment Gateway','Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Use AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click checkout with Link.','{}','pending','woocommerce.com','2025-08-29 01:34:34',NULL,0,'plain','',0,0,'info'),(140,'UPS-promo-RIN-WCS-Aug-25','marketing','en_US','Get up to $100 off your first UPS shipments','For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.','{}','pending','woocommerce.com','2025-09-10 11:05:32',NULL,0,'plain','',0,0,'info'),(141,'UPS-promo-RIN-WCST-Aug-25','marketing','en_US','Get up to $100 off your first UPS shipments','For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.','{}','pending','woocommerce.com','2025-09-10 11:05:32',NULL,0,'plain','',0,0,'info'),(142,'square_ordersync_upgrade_q3_2025','marketing','en_US','You asked, we delivered — order sync is here for Square','Update your Square extension to v5.0 to access <a href=\"https://woocommerce.com/document/woocommerce-square/sync-settings/sync-orders-between-woocommerce-and-square/\">automatic order syncing</a>. Manage your online sales in Square, keep reports accurate, and save time with order updates visible across both platforms.','{}','pending','woocommerce.com','2025-09-11 11:55:43',NULL,0,'plain','',0,0,'info'),(143,'klaviyo_q3_2025','marketing','en_US','Smarter marketing starts with Woo x Klaviyo','Personalize every customer interaction with Klaviyo, Woo\'s preferred marketing automation solution. Advanced segmentation based on real customer behavior lets you create email and SMS campaigns focused on driving loyalty and revenue. So you can grow sales while simplifying your stack.','{}','pending','woocommerce.com','2025-09-17 01:01:56',NULL,0,'plain','',0,0,'info'),(144,'pinterest_q3_20252','marketing','en_US','More visibility, smarter campaigns','Connect your store to Pinterest via the Conversions API, a new feature in the latest version of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Get started today — connect and sync your catalog using the Conversions API.','{}','pending','woocommerce.com','2025-09-24 01:51:38',NULL,0,'plain','',0,0,'info'),(145,'pinterest_q4_2025','marketing','en_US','Maximize conversions with Pinterest','Connect your store to Pinterest via the Conversions API, now part of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Sync your catalog and create your first ad today.','{}','pending','woocommerce.com','2025-10-22 02:11:39',NULL,0,'plain','',0,0,'info'),(146,'paypaladvantage_q4_2025','marketing','en_US','PayPal Checkout offer: Get 40% back on fees for 3 months','Download and activate PayPal Payments in your WooCommerce admin, then complete your first transaction by 15 December 2025 to get 40% back on PayPal transaction fees — up to £2,000 for 3 months. PayPal Checkout works with your existing checkout. See terms: paypal.com/uk/campaign/paypalmerchantpromotion/terms.','{}','pending','woocommerce.com','2025-11-05 01:05:07',NULL,0,'plain','',0,0,'info'),(147,'reddit_q4_2025','marketing','en_US','New: Reach high-intent shoppers on Reddit','Sync your catalog and pixel with Reddit for WooCommerce. Launch your ads faster on Reddit and connect with their 400M+ weekly active users and shoppers who turn to this platform for authentic conversations and recommendations.','{}','pending','woocommerce.com','2025-11-14 01:11:51',NULL,0,'plain','',0,0,'info'),(148,'bfcm_general_sale_q4_2025','marketing','en_US','Save up to 40% on extensions and themes','For a limited time, take up to 40% off nearly everything in our Marketplace. It’s the perfect moment to give your store a holiday boost and level up for 2026. Sale ends December 2, 2025, at 14:00 UTC.','{}','pending','woocommerce.com','2025-11-19 14:33:26',NULL,0,'plain','',0,0,'info'),(149,'paypal-carding-recaptcha-dec-25','update','en_US','Activate PayPal fraud management','PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.','{}','pending','woocommerce.com','2025-12-04 01:11:08',NULL,0,'plain','',0,0,'info'),(150,'Googleupdate_q4_2025','marketing','en_US','Make every ad dollar count this holiday season','Google for WooCommerce now includes Budget Recommendations. Install the latest version and get personalized suggestions on where to optimize campaign budgets to reach more holiday shoppers this season.','{}','pending','woocommerce.com','2025-12-05 01:01:44',NULL,0,'plain','',0,0,'info'),(151,'holiday_shipping_deadlines_WCST_2025','marketing','en_US','Holiday shipping deadlines','Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.','{}','pending','woocommerce.com','2025-12-11 18:49:46',NULL,0,'plain','',0,0,'info'),(152,'holiday_shipping_deadlines_WCS_2025','marketing','en_US','Holiday shipping deadlines','Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.','{}','pending','woocommerce.com','2025-12-11 18:49:46',NULL,0,'plain','',0,0,'info'),(153,'stripe_agenticcommerce_3PDS_q4_2025','marketing','en_US','Get more from Stripe with the official extension','Switch to the official extension co-developed with Stripe for the latest features and best performance. Get access to personalized checkout options, early support for AI shopping through Stripe’s <a href=\"https://woocommerce.com/posts/stripe-agentic-commerce-suite-for-woocommerce/\">Agentic Commerce Suite</a>, and more.','{}','pending','woocommerce.com','2025-12-18 20:20:50',NULL,0,'plain','',0,0,'info'),(154,'snap_q4_2025','marketing','en_US','New: Reach a new audience on Snapchat','88% of Snapchatters love to shop, and 40% aren\'t active on other social platforms. Connect with them and grow your business using Snapchat for WooCommerce, our new official extension. Sync your products, launch ad campaigns, and track results — all from your Woo dashboard.','{}','pending','woocommerce.com','2025-12-19 01:15:26',NULL,0,'plain','',0,0,'info'),(155,'WC10.4.3-security-update-12-22-2025','update','en_US','An important update is required for WooCommerce','<strong>Please update to WooCommerce 10.4.3 to resolve a security issue.</strong> This update addresses an issue with the WooCommerce Store API that may have made guest order information visible to other logged in users. See the <a href=\"https://developer.woocommerce.com/2025/12/22/store-api-vulnerability-patched-in-woocommerce-8-1/\" target=\"_blank\">Woo Developer blog</a> for more information.','{}','pending','woocommerce.com','2025-12-22 20:58:08',NULL,0,'plain','',0,0,'info'),(156,'downloads-sub-Jan2026-RIN','marketing','en_US','WooCommerce Subscription Downloads is now part of WooCommerce Subscriptions','WooCommerce Subscriptions now allows you to include simple and variable downloadable products with your subscriptions. Streamline your subscription downloads by updating to the latest version of WooCommerce Subscriptions today.','{}','pending','woocommerce.com','2026-01-08 01:05:42',NULL,0,'plain','',0,0,'info'),(157,'paypal-carding-recaptcha-jan-26','update','en_US','Fraud protection is now required — enable today','Card networks like Visa and Mastercard now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.','{}','pending','woocommerce.com','2026-01-13 01:36:57',NULL,0,'plain','',0,0,'info'),(158,'USPS API Migration_RIN_Jan2026','marketing','en_US','Upgrade to USPS Shipping REST API by January 25','USPS is retiring the legacy Web Tools API on January 25, 2026. If you’re using the USPS Shipping Method extension with the legacy API, live USPS shipping rates will longer be shown at checkout. Migrate to the REST API now to avoid disruption.','{}','pending','woocommerce.com','2026-01-14 00:54:34',NULL,0,'plain','',0,0,'info'),(159,'existing_square_bitcoin_promotion_q1_2026','marketing','en_US','Take bitcoin payments in Square with 0% fees in 2026','Your Square POS can now accept in-person bitcoin payments, with near-instant settlement and no chargebacks. Enable it today and pay zero fees through 2026. T&amp;Cs apply.','{}','pending','woocommerce.com','2026-01-22 21:00:08',NULL,0,'plain','',0,0,'info'),(160,'prospects_square_bitcoin_promotion_q1_2026','marketing','en_US','Take bitcoin payments in Square with 0% fees in 2026','Accept in-person <a href=\"https://woocommerce.com/posts/square-bitcoin-launch\">bitcoin payments</a> with Square POS — and pay zero fees on all bitcoin transactions through 2026. Get near-instant settlement and total protection from chargebacks.','{}','pending','woocommerce.com','2026-01-22 21:00:08',NULL,0,'plain','',0,0,'info'),(161,'reddit_q1_2026','marketing','en_US','Start advertising on Reddit with a $500 bonus','Make the most of our new Reddit integration with $500 in Reddit Ads! For a limited time, new advertisers who spend $500 in Reddit Ads Manager over 30 days will get $500 in ad credit. Your bonus credit unlocks automatically when you hit $500 in spend. Use your credit within 30 days.','{}','pending','woocommerce.com','2026-02-05 07:33:18',NULL,0,'plain','',0,0,'info'),(162,'wc-admin-scheduled-updates-promotion','info','en_US','O Analytics agora oferece suporte a atualizações agendadas','Isso proporciona melhor desempenho para sua loja. Ative em Analytics &gt; Configurações.','{}','unactioned','woocommerce-admin','2026-02-08 07:31:34',NULL,0,'plain','',0,0,'info'),(163,'Googleupdate_q1_2026','marketing','en_US','Make every ad dollar count','Google for WooCommerce now includes Budget Recommendations. Promote your products across Google — from Search to YouTube and beyond — and get personalized suggestions on where to optimize campaign budgets to reach more shoppers.','{}','pending','woocommerce.com','2026-02-11 07:37:36',NULL,0,'plain','',0,0,'info'),(164,'Mailchimp-API-maintenance-feb-2026','update','en_US','Mailchimp Maintenance Feb 28','Mailchimp will be carrying out planned API maintenance on February 28 from 11am – 4pm EST. During that time, you may see brief sync interruptions in Mailchimp for WooCommerce. Most data will catch up automatically. See the <a href=\"https://developer.woocommerce.com/2026/02/27/mailchimp-api-maintenance-february-28/\" target=\"_blank\">Woo Developer blog</a> for more information.','{}','pending','woocommerce.com','2026-02-27 21:30:48',NULL,0,'plain','',0,0,'info'),(165,'RIN-WC-Security-Update-admin-update-March-2026','update','en_US','An important update is required for WooCommerce','<strong>Update to WooCommerce 10.5.3 or the latest version to resolve a security issue.</strong> This update addresses a vulnerability in WooCommerce versions 5.4 to 10.5.2 that could have permitted unauthorized admin account access. See the <a href=\"https://developer.woocommerce.com/2026/03/02/store-api-vulnerability-patched-in-woocommerce-5-4/\" target=\"_blank\">Woo Developer blog</a> for more information.','{}','pending','woocommerce.com','2026-03-03 02:22:16',NULL,0,'plain','',0,0,'info'),(166,'USPS_Scan_Form_Mar2026','marketing','en_US','New: Save time shipping with USPS SCAN Form','USPS SCAN Form consolidates multiple shipments into one scannable sheet. Hand off all your orders at once — no more scanning packages individually. Select “Create SCAN Form” under your orders to try it today.','{}','pending','woocommerce.com','2026-03-11 22:20:57',NULL,0,'plain','',0,0,'info'),(167,'usps-surcharge-apr2026','marketing','en_US','Heads up: USPS rates increasing 8% on April 26','USPS is adding a temporary 8% surcharge on Priority Mail, Priority Mail Express, Ground Advantage, and Parcel Select from April 26, 2026 through January 17, 2027. WooCommerce Shipping discounted rates still apply.','{}','pending','woocommerce.com','2026-04-21 21:22:03',NULL,0,'plain','',0,0,'info'),(168,'stripe-woo-gateway-update-april2026','update','en_US','A critical update is required for Stripe for WooCommerce','<strong>A critical update is required for Stripe for WooCommerce</strong> that addresses possible payment issues. Please update the WooCommerce Stripe Gateway to v10.6.1 immediately.','{}','pending','woocommerce.com','2026-04-24 00:30:14',NULL,0,'plain','',0,0,'info'),(169,'klaviyo_q2_2026','marketing','en_US','Attn Woo: Klaviyo Customer Hub is here','Drive revenue and reduce your support burden by giving customers a single place to manage their orders, returns, subscriptions, loyalty, and more. Enable Customer Hub in your Klaviyo dashboard today, available on all paid plans.','{}','pending','woocommerce.com','2026-04-30 00:45:12',NULL,0,'plain','',0,0,'info'),(170,'existing_square_discountcodes_gtm_q2_2026','marketing','en_US','Automatic coupon sync now available in Square','The discount codes you create in your Square dashboard will now work directly on your WooCommerce checkout — no need to manually sync coupons. Manage all of your discounts from one place with automatic redemption count updates.','{}','pending','woocommerce.com','2026-05-15 01:54:11',NULL,0,'plain','',0,0,'info'),(171,'prospects_square_discountcodes_gtm_q2_2026','marketing','en_US','Square now offers automatic coupon sync','Big news for smoother cross-channel sales: you can now create discount codes in Square and have them work directly at checkout on your Woo store, no manual sync required. Save time when you manage your discounts from one place — and keep your online and in-person sales seamlessly connected.','{}','pending','woocommerce.com','2026-05-19 07:54:22',NULL,0,'plain','',0,0,'info'),(172,'paypal_bnpl_mx_promo_Q2_2026','marketing','en_US','Bigger carts, lower fees: enable installments today','Merchants using PayPal installments see up to 205% higher average order values. Activate 3-installment payments from your PayPal Business dashboard and get 30% off transaction fees for 90 days. Sign up by October 15, 2026. Limited availability. Terms apply.','{}','pending','woocommerce.com','2026-05-20 13:35:42',NULL,0,'plain','',0,0,'info'),(173,'stripe_adaptivepricing_q2_2026','marketing','en_US','Sell internationally with Adaptive Pricing from Stripe','Adaptive Pricing is now available in the official Stripe for WooCommerce extension. Show prices in local currency across 150+ countries, lifting cross-border revenue by 17.8%. Shoppers pay exactly what they see at checkout, while you settle in your base currency.','{}','pending','woocommerce.com','2026-06-02 17:12:13',NULL,0,'plain','',0,0,'info');
